// Service worker (spec §16): precache every game file, cache-first for the
// game, network-only for Supabase (any other origin). A new version waits
// until the player taps the "update available" toast.
// The block below is generated by `node tools/build-precache.mjs`.

// PRECACHE-START
const VERSION = '63e2f6feb038';
const FILES = [
  './',
  './index.html',
  './manifest.webmanifest',
  './src/art/bitmap.js',
  './src/art/bosses.js',
  './src/art/enemies.js',
  './src/art/font.js',
  './src/art/galaxy.js',
  './src/art/icon.js',
  './src/art/index.js',
  './src/art/medals.js',
  './src/art/palettes.js',
  './src/art/rotsprite.js',
  './src/art/sprites/bosses.js',
  './src/art/sprites/droids.js',
  './src/art/sprites/droids2.js',
  './src/art/sprites/emblems.js',
  './src/art/sprites/enemies.js',
  './src/art/sprites/extras.js',
  './src/art/sprites/kamino.js',
  './src/art/sprites/planets.js',
  './src/art/sprites/posts.js',
  './src/art/sprites/rifle.js',
  './src/art/sprites/troopers.js',
  './src/art/sprites/turrets.js',
  './src/art/sprites/turrets2.js',
  './src/art/tilemap.js',
  './src/art/towers.js',
  './src/art/ui.js',
  './src/art/vfx.js',
  './src/config.js',
  './src/data/balance.js',
  './src/data/enemies.js',
  './src/data/levels/geonosis.js',
  './src/data/levels/index.js',
  './src/data/levels/kamino-1.js',
  './src/data/levels/kamino.js',
  './src/data/levels/kashyyyk.js',
  './src/data/levels/mustafar.js',
  './src/data/levels/umbara.js',
  './src/data/levels/waves.js',
  './src/data/meta.js',
  './src/data/music.js',
  './src/data/rules.js',
  './src/data/towers.js',
  './src/engine/assets.js',
  './src/engine/atlas.js',
  './src/engine/audio.js',
  './src/engine/camera.js',
  './src/engine/input.js',
  './src/engine/pool.js',
  './src/engine/renderer.js',
  './src/engine/rng.js',
  './src/engine/scaling.js',
  './src/fx/fx.js',
  './src/main.js',
  './src/save/cloud.js',
  './src/save/schema.js',
  './src/save/storage.js',
  './src/sim/rules.js',
  './src/sim/sim.js',
  './src/sim/spatial.js',
  './src/ui/account.js',
  './src/ui/bench.js',
  './src/ui/debug.js',
  './src/ui/game-screen.js',
  './src/ui/meta-screens.js',
  './src/ui/screens.js',
  './src/ui/settings.js',
  './src/ui/tutorial.js',
  './src/ui/ui.js',
  './src/ui/world.js',
  './vendor/supabase.js',
  './icons/apple-touch-icon.png',
  './icons/icon-192.png',
  './icons/icon-512.png',
  './icons/maskable-512.png'
];
// PRECACHE-END

const CACHE = `republic-frontline-${VERSION}`;

self.addEventListener('install', (e) => {
  e.waitUntil(caches.open(CACHE).then((c) => c.addAll(FILES)));
});

self.addEventListener('activate', (e) => {
  e.waitUntil(
    caches.keys()
      .then((keys) => Promise.all(keys.filter((k) => k.startsWith('republic-frontline-') && k !== CACHE).map((k) => caches.delete(k))))
      .then(() => self.clients.claim()),
  );
});

self.addEventListener('message', (e) => {
  if (e.data === 'skipWaiting') self.skipWaiting();
});

self.addEventListener('fetch', (e) => {
  const req = e.request;
  const url = new URL(req.url);
  if (req.method !== 'GET' || url.origin !== self.location.origin) return; // Supabase etc.: network only
  e.respondWith((async () => {
    const cache = await caches.open(CACHE);
    // navigations (any ?query) get the cached shell
    const hit = req.mode === 'navigate' ? await cache.match('./index.html') : await cache.match(req, { ignoreSearch: true });
    if (hit) return hit;
    try {
      return await fetch(req);
    } catch {
      return (await cache.match('./index.html')) || Response.error();
    }
  })());
});
